<?php defined('ABSPATH')||exit;$style=get_theme_mod('rss_prism_footer_style','light');$classes='site-footer site-footer--'.sanitize_html_class($style).' rp-footer-columns--'.sanitize_html_class(get_theme_mod('rss_prism_footer_columns','three')).' rp-footer-logo--'.sanitize_html_class(get_theme_mod('rss_prism_footer_logo_position','left'));?><footer class="<?php echo esc_attr($classes); ?>"><div class="site-footer__main rp-container"><div class="site-footer__identity"><?php if(get_theme_mod('rss_prism_footer_show_logo',true)&&has_custom_logo()):?><div class="site-footer__logo"><?php the_custom_logo();?></div><?php else:?><a class="site-footer__brand" href="<?php echo esc_url(home_url('/'));?>"><?php bloginfo('name');?></a><?php endif;?><p class="site-footer__copy"><?php echo esc_html(get_theme_mod('rss_prism_footer_text','Ideas made clearer.'));?></p></div><?php if(get_theme_mod('rss_prism_footer_columns','three')!=='one'):?><div class="site-footer__links"><?php if(get_theme_mod('rss_prism_footer_show_widgets',true)&&is_active_sidebar('footer-1')):dynamic_sidebar('footer-1');else:?><h2><?php esc_html_e('Explore','rss-prism');?></h2><?php if(get_theme_mod('rss_prism_footer_show_menu',true))wp_nav_menu(array('theme_location'=>'footer','container'=>false,'fallback_cb'=>false));endif;?></div><?php endif;?><?php if(get_theme_mod('rss_prism_footer_columns','three')==='three'):?><div class="site-footer__extra"><?php if(get_theme_mod('rss_prism_footer_show_widgets',true)&&is_active_sidebar('footer-2')):dynamic_sidebar('footer-2');else:?><h2><?php esc_html_e('Stay connected','rss-prism');?></h2><p class="site-footer__copy"><?php esc_html_e('Use footer widgets to share contact details and helpful links.','rss-prism');?></p><?php endif;?></div><?php endif;?></div><div class="site-footer__bottom rp-container"><p><?php $copyright=trim((string)get_theme_mod('rss_prism_footer_copyright',''));if($copyright){echo esc_html($copyright);}else{echo '© '.esc_html(wp_date('Y')).' '.esc_html(get_bloginfo('name')).'. '.esc_html__('All rights reserved.','rss-prism');} ?></p><?php if(get_theme_mod('rss_prism_footer_show_menu',true))wp_nav_menu(array('theme_location'=>'footer','container'=>'nav','container_class'=>'footer-navigation','fallback_cb'=>false));?></div></footer><?php if(get_theme_mod('rss_prism_show_back_to_top',true)):?><a class="rp-back-to-top" href="#top" aria-label="<?php esc_attr_e('Back to top','rss-prism');?>">↑ <span><?php esc_html_e('Top','rss-prism');?></span></a><?php endif;?><?php wp_footer();?></body></html>